'use strict';

// Uncomment the next lines to use your game instance in the browser
const Game = require('../modules/Game.class');
const game = new Game();

function fix100vh() {
  const vh = window.innerHeight * 0.01;

  document.documentElement.style.setProperty('--vh', `${vh}px`);
}

window.addEventListener('resize', fix100vh);
window.addEventListener('load', fix100vh);

// Write your code here

function renderBoard() {
  const cells = document.querySelectorAll('.field-cell');

  for (let i = 0; i < cells.length; i++) {
    const row = Math.floor(i / 4);
    const col = i % 4;
    const value = game.board[row][col];
    const cell = cells[i];

    cell.className = 'field-cell';

    if (value === 0) {
      cell.textContent = '';
    } else {
      cell.textContent = value;
      cell.classList.add(`field-cell--${value}`);
    }
  }
}

const startButton = document.querySelector('.start');

startButton.addEventListener('click', () => {
  game.start();
  renderBoard();
  updateScore();
  updateMessage();
  toggleButtons();
});

const restartButton = document.querySelector('.button.restart');

restartButton.addEventListener('click', () => {
  game.restart();
  updateScore();
  renderBoard();
  updateMessage();
  toggleButtons();
});

function toggleButtons() {
  if (game.getStatus() === 'idle') {
    startButton.classList.remove('hidden');
    restartButton.classList.add('hidden');
  } else {
    startButton.classList.add('hidden');
    restartButton.classList.remove('hidden');
  }
}

window.addEventListener('keydown', (e) => {
  switch (e.key) {
    case 'ArrowLeft':
      game.moveLeft();
      updateScore();
      renderBoard();
      updateMessage();
      game.updateStatus();

      break;
    case 'ArrowRight':
      game.moveRight();
      updateScore();
      renderBoard();
      updateMessage();
      game.updateStatus();

      break;
    case 'ArrowUp':
      game.moveUp();
      updateScore();
      renderBoard();
      updateMessage();
      game.updateStatus();

      break;
    case 'ArrowDown':
      game.moveDown();
      updateScore();
      renderBoard();
      updateMessage();
      game.updateStatus();

      break;
  }

  renderBoard();
});

const scoreElement = document.querySelector('.game-score');

function updateScore() {
  scoreElement.textContent = game.getScore();
  renderBoard();
}

function updateMessage() {
  const win = document.querySelector('.message-win');
  const lose = document.querySelector('.message-lose');
  const start = document.querySelector('.message-start');
  const statusGame = game.getStatus();

  win.classList.add('hidden');
  lose.classList.add('hidden');
  start.classList.add('hidden');

  if (statusGame === 'win') {
    win.classList.remove('hidden');
  } else if (statusGame === 'lose') {
    lose.classList.remove('hidden');
  } else if (statusGame === 'idle') {
    start.classList.remove('hidden');
  }
}

let touchStartX = 0;
let touchStartY = 0;

document.addEventListener('touchstart', (e) => {
  touchStartX = e.touches[0].clientX;
  touchStartY = e.touches[0].clientY;
});

document.addEventListener('touchend', (e) => {
  const touchEndX = e.changedTouches[0].clientX;
  const touchEndY = e.changedTouches[0].clientY;

  const diffX = touchEndX - touchStartX;
  const diffY = touchEndY - touchStartY;

  if (Math.abs(diffX) > Math.abs(diffY)) {
    if (diffX > 30) {
      handleMove('ArrowRight');
    } else if (diffX < -30) {
      handleMove('ArrowLeft');
    }
  } else {
    if (diffY > 30) {
      handleMove('ArrowDown');
    } else if (diffY < -30) {
      handleMove('ArrowUp');
    }
  }
});

function handleMove(key) {
  if (game.getStatus() !== 'playing') {
    return;
  }

  if (key === 'ArrowUp') {
    game.moveUp();
  }

  if (key === 'ArrowDown') {
    game.moveDown();
  }

  if (key === 'ArrowLeft') {
    game.moveLeft();
  }

  if (key === 'ArrowRight') {
    game.moveRight();
  }

  updateScore();
  renderBoard();
  game.updateStatus();
  updateMessage();
  toggleButtons();
}
